/// <summary>
/// MPJ_21275_BackOrders
/// Extension of InventSite form
/// </summary>
[ExtensionOf(Formstr(InventSite))]
final class METInventSite_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_21275_BackOrders
    /// Based on legal entity allow backorder parameter on site level able to access the allow back order check box
    /// </summary>
    public void init()
    {
        CustParameters  custParameters  = CustParameters::find();
      
        next init();

        if (custParameters.METAllowBackOrders == NoYes::Yes)
        {
            METAllowBackOrders.allowEdit(true);
        }
        else
        {
            METAllowBackOrders.allowEdit(false);
        }
    }
